def transform(g):
    h,w=len(g),len(g[0])
    marked=[[False]*w for _ in range(h)]
    for r in range(h-4):
        for c in range(w-4):
            color=g[r][c]
            if all(g[i][j]==color for i in range(r,r+5) for j in range(c,c+5)):
                for i in range(r,r+5):
                    for j in range(c,c+5): marked[i][j]=True
    return [[4 if marked[i][j] else g[i][j] for j in range(w)] for i in range(h)]
